mapper.select:
SELECT DISTINCT t.PADDING_CODE FROM T_DJ_SCHEDULE_RESULT t WHERE t.FACTORY_CODE = #{factoryCode} AND t.SCHEDULE_DATE BETWEEN #{thresholdDate} AND #{scheduleDate} AND t.PADDING_CODE IN
#{code}
AND (t.CLASS1_PLAN_QTY IS NOT NULL AND t.CLASS1_PLAN_QTY > 0 OR t.CLASS2_PLAN_QTY IS NOT NULL AND t.CLASS2_PLAN_QTY > 0 OR t.CLASS3_PLAN_QTY IS NOT NULL AND t.CLASS3_PLAN_QTY > 0 OR t.CLASS4_PLAN_QTY IS NOT NULL AND t.CLASS4_PLAN_QTY > 0 OR t.CLASS5_PLAN_QTY IS NOT NULL AND t.CLASS5_PLAN_QTY > 0 OR t.CLASS6_PLAN_QTY IS NOT NULL AND t.CLASS6_PLAN_QTY > 0)
